function(container, apiUrl, tables) {
  // 業務ロジックのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aiLogic || {};

  let editingModelId = null;

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#model-list-tbody");
    if (!tbody) return;
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.モデル名 || ""}</td>
        <td>${r.対象店舗名 || ""}</td>
        <td>${r.対象商品カテゴリ || ""}</td>
        <td>${r.アルゴリズム || ""}</td>
        <td>${r.モデル精度目標値 || ""}%</td>
        <td><span class="status-badge ${r.ステータス === '作成完了' ? 'success' : 'pending'}">${r.ステータス || ""}</span></td>
        <td>${r.作成日時 ? new Date(r.作成日時).toLocaleDateString() : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>
    `).join("");

    // 編集・削除ボタンのイベントハンドラを再設定
    attachRowEventHandlers();
  }

  // 行のイベントハンドラを設定
  function attachRowEventHandlers() {
    // 編集ボタン
    container.querySelectorAll(".edit-btn").forEach(btn => {
      btn.addEventListener("click", async (e) => {
        const modelId = e.target.getAttribute("data-id");
        await editModel(modelId);
      });
    });

    // 削除ボタン
    container.querySelectorAll(".delete-btn").forEach(btn => {
      btn.addEventListener("click", async (e) => {
        const modelId = e.target.getAttribute("data-id");
        if (confirm("このモデルを削除しますか？")) {
          await deleteModel(modelId);
        }
      });
    });
  }

  // モデル編集
  async function editModel(modelId) {
    try {
      const models = await window.aivicApi.list(5); // モデル設定テーブル
      const model = models.find(m => m.id == modelId);
      if (!model) {
        window.aivicNotify.error("モデルが見つかりません");
        return;
      }

      editingModelId = modelId;

      // フォームに値を設定
      const modelNameInput = container.querySelector("#model-name");
      const targetStoreSelect = container.querySelector("#target-store");
      const algorithmSelect = container.querySelector("#algorithm");
      const accuracyInput = container.querySelector("#accuracy-target");
      const trainingPeriodInput = container.querySelector("#training-period");

      if (modelNameInput) modelNameInput.value = model.モデル名 || "";
      if (targetStoreSelect) targetStoreSelect.value = model.対象店舗ID || "";
      if (algorithmSelect) algorithmSelect.value = model.アルゴリズム || "";
      if (accuracyInput) accuracyInput.value = model.モデル精度目標値 || "";
      if (trainingPeriodInput) trainingPeriodInput.value = model.学習期間 || "";

    } catch (error) {
      window.aivicNotify.error("モデル編集エラー: " + error.message);
    }
  }

  // モデル削除
  async function deleteModel(modelId) {
    try {
      await window.aivicApi.delete(5, modelId);
      window.aivicNotify.success("モデルを削除しました");
      await loadModels();
    } catch (error) {
      window.aivicNotify.error("削除エラー: " + error.message);
    }
  }

  // モデル一覧読み込み
  async function loadModels() {
    try {
      const models = await window.aivicApi.list(5);
      renderRows(models);
    } catch (error) {
      window.aivicNotify.error("モデル一覧の読み込みに失敗しました: " + error.message);
    }
  }

  // 店舗一覧読み込み
  async function loadStores() {
    try {
      const stores = await window.aivicApi.list(1); // 店舗テーブル
      const targetStoreSelect = container.querySelector("#target-store");
      if (targetStoreSelect) {
        targetStoreSelect.innerHTML = '<option value="">店舗を選択</option>' +
          stores.map(store => `<option value="${store.id}">${store.店舗名}</option>`).join("");
      }
    } catch (error) {
      window.aivicNotify.error("店舗一覧の読み込みに失敗しました: " + error.message);
    }
  }

  // モデル保存
  async function saveModel() {
    try {
      const modelNameInput = container.querySelector("#model-name");
      const targetStoreSelect = container.querySelector("#target-store");
      const algorithmSelect = container.querySelector("#algorithm");
      const accuracyInput = container.querySelector("#accuracy-target");
      const trainingPeriodInput = container.querySelector("#training-period");

      if (!modelNameInput?.value || !targetStoreSelect?.value || !algorithmSelect?.value) {
        window.aivicNotify.error("必須項目を入力してください");
        return;
      }

      // 業務ロジックを使用してデータ収集・検証
      const storeId = parseInt(targetStoreSelect.value);

      // 売上データ収集
      const salesData = await collectSalesData(storeId);
      if (!salesData || salesData.length === 0) {
        window.aivicNotify.error("対象店舗の売上データが見つかりません");
        return;
      }

      // 商品別分類
      const productClassified = classifySalesDataByProduct(salesData);

      // 有効な商品データのフィルタリング
      const validProductData = filterValidProductData(productClassified);
      if (!validProductData || validProductData.length === 0) {
        window.aivicNotify.error("有効な商品データが不足しています");
        return;
      }

      // 学習期間の検証
      const trainingPeriod = parseInt(trainingPeriodInput?.value || 30);
      const isValidPeriod = validateComparisonPeriod(trainingPeriod);
      if (!isValidPeriod) {
        window.aivicNotify.error("学習期間が不正です");
        return;
      }

      // 外部データ収集
      const weatherData = await collectWeatherData(storeId);
      const eventData = await collectEventData(storeId);
      const seasonalData = collectSeasonalData(salesData);

      // 相関分析
      const weatherCorrelation = analyzeCorrelationSalesWeather(salesData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(salesData, eventData);
      const seasonCorrelation = analyzeCorrelationSalesSeason(salesData, seasonalData);

      // 履歴データとの比較
      const historicalComparison = compareWithHistoricalData(salesData);

      const modelData = {
        モデル名: modelNameInput.value,
        対象店舗ID: storeId,
        対象店舗名: targetStoreSelect.options[targetStoreSelect.selectedIndex].text,
        アルゴリズム: algorithmSelect.value,
        モデル精度目標値: parseFloat(accuracyInput?.value || 0),
        学習期間: trainingPeriod,
        ステータス: "作成中",
        作成日時: new Date().toISOString(),
        売上データ件数: salesData.length,
        有効商品数: validProductData.length,
        天気相関係数: weatherCorrelation,
        イベント相関係数: eventCorrelation,
        季節相関係数: seasonCorrelation,
        履歴比較結果: historicalComparison
      };

      if (editingModelId) {
        await window.aivicApi.update(5, editingModelId, modelData);
        window.aivicNotify.success("モデルを更新しました");
      } else {
        await window.aivicApi.save(5, modelData);
        window.aivicNotify.success("モデルを作成しました");
      }

      // フォームリセット
      resetForm();
      await loadModels();

    } catch (error) {
      window.aivicNotify.error("保存エラー: " + error.message);
    }
  }

  // フォームリセット
  function resetForm() {
    editingModelId = null;
    const form = container.querySelector("#model-form");
    if (form) form.reset();
  }

  // モデル学習実行
  async function executeTraining(modelId) {
    try {
      const models = await window.aivicApi.list(5);
      const model = models.find(m => m.id == modelId);
      if (!model) {
        window.aivicNotify.error("モデルが見つかりません");
        return;
      }

      // ステータス更新
      await window.aivicApi.update(5, modelId, {
        ...model,
        ステータス: "学習中"
      });

      window.aivicNotify.success("モデル学習を開始しました");
      await loadModels();

      // 実際の学習処理は非同期で実行される想定
      setTimeout(async () => {
        try {
          await window.aivicApi.update(5, modelId, {
            ...model,
            ステータス: "作成完了",
            完了日時: new Date().toISOString()
          });
          window.aivicNotify.success("モデル学習が完了しました");
          await loadModels();
        } catch (error) {
          window.aivicNotify.error("学習完了処理エラー: " + error.message);
        }
      }, 3000);

    } catch (error) {
      window.aivicNotify.error("学習実行エラー: " + error.message);
    }
  }

  // イベントハンドラの設定
  function attachEventHandlers() {
    // 保存ボタン
    const saveBtn = container.querySelector("#save-model-btn");
    if (saveBtn) {
      saveBtn.addEventListener("click", saveModel);
    }

    // キャンセルボタン
    const cancelBtn = container.querySelector("#cancel-btn");
    if (cancelBtn) {
      cancelBtn.addEventListener("click", resetForm);
    }

    // 学習実行ボタン
    const trainBtn = container.querySelector("#train-model-btn");
    if (trainBtn) {
      trainBtn.addEventListener("click", async () => {
        if (editingModelId) {
          await executeTraining(editingModelId);
        } else {
          window.aivicNotify.error("学習するモデルを選択してください");
        }
      });
    }

    // 新規作成ボタン
    const newBtn = container.querySelector("#new-model-btn");
    if (newBtn) {
      newBtn.addEventListener("click", resetForm);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      await loadStores();
      await loadModels();
      attachEventHandlers();
    } catch (error) {
      window.aivicNotify.error("初期化エラー: " + error.message);
    }
  }

  // 初期化実行
  initialize();
}
